let _markdown = "\n\nUsage [#usage]\n\nClient Component [#client-component]\n\n```tsx\nimport { DynamicCodeBlock } from 'fumadocs-ui/components/dynamic-codeblock';\n\nexport function MyComp() {\n  const code = `console.log(\"Hello World\")`;\n\n  return <DynamicCodeBlock lang=\"ts\" code={code} />;\n}\n```\n\n<FeedbackBlock\n  id=\"065e3bbe02653301\"\n  body=\"Unlike the MDX CodeBlock component, this is a client component that can be used without MDX.\nIt highlights the code with Shiki and use the default component to render it.\"\n>\n  Unlike the MDX [`CodeBlock`](/docs/ui/components/codeblock) component, this is a client component that can be used without MDX.\n  It highlights the code with Shiki and use the default component to render it.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"d6295c05503596b3\" body=\"Features:\">\n  Features:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"ebb5edba1cffe22e\" body=\"using React.js 19 Suspense.can be pre-rendered on server.load languages and themes on browser lazily.\">\n  * using React.js 19 Suspense.\n  * can be pre-rendered on server.\n  * load languages and themes on browser lazily.\n</FeedbackBlock>\n\nOptions [#options]\n\n```tsx\nimport { DynamicCodeBlock } from 'fumadocs-ui/components/dynamic-codeblock';\n\n<DynamicCodeBlock\n  lang=\"ts\"\n  code='console.log(\"Hello World\")'\n  options={{\n    themes: {\n      light: 'github-light',\n      dark: 'github-dark',\n    },\n    components: {\n      // override components (e.g. `pre` and `code`)\n    },\n    // other Shiki options\n  }}\n/>;\n```\n\nServer Component [#server-component]\n\n<FeedbackBlock id=\"d35de194ec203a4e\" body=\"For a server component equivalent, you can use the built-in utility from core:\">\n  For a server component equivalent, you can use the built-in utility from core:\n</FeedbackBlock>\n\n```tsx\nimport * as Base from 'fumadocs-ui/components/codeblock';\nimport { highlight } from 'fumadocs-core/highlight';\nimport { type HTMLAttributes } from 'react';\n\nexport async function CodeBlock({\n  code,\n  lang,\n  ...rest\n}: HTMLAttributes<HTMLElement> & {\n  code: string;\n  lang: string;\n}) {\n  const rendered = await highlight(code, {\n    lang,\n    components: {\n      pre: (props) => <Base.Pre {...props} />,\n    },\n    // other Shiki options\n  });\n\n  return <Base.CodeBlock {...rest}>{rendered}</Base.CodeBlock>;\n}\n\n```\n";
